import numpy as np


def pairwise_distances(a, b):
    n, m = len(a), len(b)
    out = np.empty((n, m))
    for i in range(n):
        for j in range(m):
            out[i, j] = np.sqrt(np.sum((a[i] - b[j]) ** 2))
    return out


def nearest(a, b):
    return pairwise_distances(a, b).argmin(axis=1)

