import numpy as np


def pairwise_distances(a, b):
    diff = a[:, None, :] - b[None, :, :]
    return np.sqrt((diff ** 2).sum(axis=-1))


def nearest(a, b, chunk=1000):
    out = np.empty(len(a), dtype=np.intp)
    for start in range(0, len(a), chunk):
        stop = start + chunk
        out[start:stop] = pairwise_distances(a[start:stop], b).argmin(axis=1)
    return out
